{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Cefuroxime axetil, a cephalosporin ester prodrug sharing the same cephem core and carbamoyloxymethyl group as the query, showed 64% absolute oral bioavailability in humans, directly supporting high F for the query's prodrug ester.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Ampicillin, a polar beta-lactam with ionizable groups, had 62 ± 17% oral bioavailability in healthy fasting subjects, demonstrating that beta-lactam polarity does not preclude F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Amoxicillin, a close beta-lactam analogue, showed 93% absolute oral bioavailability at 500 mg in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Faropenem, a beta-lactam with a similar bicyclic core, showed 72–84% oral bioavailability in children, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Loracarbef, a cephalosporin, was approximately 90% bioavailable after oral administration in humans, supporting high F for the query's cephalosporin core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Perindopril, an ester prodrug of a polar carboxylic acid, had about 75% absolute oral bioavailability, supporting that ester prodrugs can achieve high F despite polar physicochemical features.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Despite unfavorable physicochemical predictions, multiple high-transfer experimental analogues—especially cephalosporin and beta-lactam ester prodrugs—show absolute oral bioavailability well above 20% (38–95%). The query's acetoxymethyl ester prodrug and cephem core align with these analogues, so F ≥ 20% is strongly supported.",
  "evidence_gaps": [
    "No direct human bioavailability data exist for the exact query molecule; the closest analogue (cefuroxime axetil) differs in the 7-acyl side chain and ester group.",
    "The query's 7-hydroxyethyl substituent is not directly represented in the analogue set, so its specific effect on absorption is inferred rather than measured.",
    "The acetoxymethyl ester may have different hydrolysis or stability kinetics than the 1-acetoxyethyl ester of cefuroxime axetil."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

